	m.Combo("").
		Put(bind(api.LockIssueOption{}), repo.LockIssue).
		Delete(repo.UnlockIssue)
}, reqToken(), reqAdmin())

if !issue.IsLocked {
	opt := &issues_model.IssueLockOptions{
		Doer:   ctx.ContextUser,
		Issue:  issue,
		Reason: reason,

reason := web.GetForm[*api.LockIssueOption](ctx).Reason
issue, err := issues_model.GetIssueByIndex(ctx, ctx.Repo.Repository.ID, ctx.PathParamInt64("index"))
if err != nil {

// reqAdmin user should be an owner or a collaborator with admin write of a repository, or site admin
func reqAdmin() func(ctx *context.APIContext) {
	return func(ctx *context.APIContext) {
		if !ctx.IsUserRepoAdmin() && !ctx.IsUserSiteAdmin() {
			ctx.APIError(http.StatusForbidden, "user should be an owner or a collaborator with admin write of a repository")
			return
		}

if !ctx.Repo.Permission.CanWriteIssuesOrPulls(issue.IsPull) {
	ctx.APIError(http.StatusForbidden, "no permission to lock this issue")
	return
}

if !issue.IsLocked {
	opt := &issues_model.IssueLockOptions{
		Doer:   ctx.ContextUser,
		Issue:  issue,
		Reason: reason,
	}

	issue.Repo = ctx.Repo.Repository
	err = issues_model.LockIssue(ctx, opt)
	if err != nil {
		ctx.APIErrorInternal(err)
		return
	}
}

ctx.Status(http.StatusNoContent)

// reqAdmin user should be an owner or a collaborator with admin write of a repository, or site admin
func reqAdmin() func(ctx *context.APIContext) {
	return func(ctx *context.APIContext) {
		if !ctx.IsUserRepoAdmin() && !ctx.IsUserSiteAdmin() {
			ctx.APIError(http.StatusForbidden, "user should be an owner or a collaborator with admin write of a repository")
			return
		}

if !ctx.Repo.Permission.CanWriteIssuesOrPulls(issue.IsPull) {
	ctx.APIError(http.StatusForbidden, "no permission to lock this issue")
	return
}

